// Retrieval — n8n Code node (Run Once for All Items).
// Input : webhook body { query, website_url, type?, top_k?, min_score? }
// Output: ONE item { query, grounded, top_score, matches:[{score,type,section,url,text}] }
// Grounding guard: if the best match scores below min_score, flag grounded=false
// so callers (sub-agents/synthesizer) know to fall back rather than invent an answer.
const helpers = this.helpers;
const OLLAMA = 'http://dental-ollama:11434';
const QDRANT = 'http://dental-qdrant:6333';
const COLL = 'clinic_kb';
const MODEL = 'nomic-embed-text';

const body = $input.first().json.body || $input.first().json || {};
const query = String(body.query || '').trim();
const website_url = body.website_url || null;
const topK = parseInt(body.top_k || 6, 10);
const minScore = typeof body.min_score === 'number' ? body.min_score : 0.55;
if (!query) throw new Error('query is required');

const e = await helpers.httpRequest({
  method: 'POST', url: OLLAMA + '/api/embeddings',
  body: { model: MODEL, prompt: query }, json: true, timeout: 30000,
});
const vector = e.embedding;

const must = [];
if (website_url) must.push({ key: 'website_url', match: { value: website_url } });
if (body.type) must.push({ key: 'type', match: { value: body.type } });
if (!body.type) must.push({ key: 'type', match: { any: ["doctor","policy","page","hours"] } });

const searchBody = { vector, limit: topK, with_payload: true };
if (must.length) searchBody.filter = { must };

const r = await helpers.httpRequest({
  method: 'POST', url: QDRANT + '/collections/' + COLL + '/points/search',
  body: searchBody, json: true, timeout: 30000,
});

const seen = new Set();
const matches = [];
for (const hit of (r.result || [])) {
  const key = (hit.payload.ext_id || '') + ':' + (hit.payload.chunk_index || 0);
  if (seen.has(key)) continue;
  seen.add(key);
  matches.push({
    score: hit.score,
    type: hit.payload.type,
    section: hit.payload.section,
    url: hit.payload.url,
    text: hit.payload.text,
  });
}

const top_score = matches.length ? matches[0].score : 0;
return [{
  json: {
    query,
    grounded: top_score >= minScore,
    top_score,
    matches,
  },
}];

// Build a grounded-answer LLM request from retriever output (Code node).
// Input : { query, grounded, top_score, matches[] } from Retrieve, plus
//         a static `agentRole`/`instructions` baked in per sub-agent workflow.
// Output: { query, grounded, oai_body } for the following OpenAI node.
// AGENT_ROLE and AGENT_RULES are injected by string-substitution at build time
// (see scripts/build_workflows.js) so this one file serves every sub-agent.
const AGENT_ROLE = 'General Knowledge Agent';
const AGENT_RULES = 'Answer questions about the clinic itself: doctors, location, contact info, policies, and about-us content, using only the context provided.';

const d = $input.first().json;
const query = d.query;
const grounded = !!d.grounded;
const matches = d.matches || [];

if (!grounded || matches.length === 0) {
  return [{
    json: {
      query, grounded: false,
      answer: null,
      needs_fallback: true,
    },
  }];
}

const context = matches.map(function (m, i) {
  return '[' + (i + 1) + '] (' + m.type + ') ' + m.text;
}).join('\n\n');

const sys = [
  'You are the ' + AGENT_ROLE + ' for a dental/orthodontic clinic chatbot.',
  AGENT_RULES,
  'CRITICAL: Only use facts present in the CONTEXT below. Never invent prices, names, hours, or policies.',
  'If the context does not fully answer the question, say what you do know and suggest contacting the clinic for specifics.',
  'Cite nothing explicitly (no [1] markers in the reply) - just write a natural, professional, concise answer (<= 80 words).',
].join('\n');

const user = 'QUESTION: ' + query + '\n\nCONTEXT:\n' + context;

return [{
  json: {
    query, grounded: true, needs_fallback: false,
    oai_body: {
      model: 'gpt-4o-mini',
      temperature: 0.2,
      messages: [
        { role: 'system', content: sys },
        { role: 'user', content: user },
      ],
    },
  },
}];
